muro__sess_res muro__sess_conn_step_word(muro__sess_st st, int dir, int tag, uint64_t word) {
  return muro__sess_word_step(st, dir, tag, word, muro__sess_conn_step);
}

int muro__sess_conn_done(muro__sess_st st) {
  if (st.key != 1) return 0;
  return muro__sess_is_done(st.key, st.at, st.stuck);
}

const char *muro__sess_conn_at(muro__sess_st st) {
  if (st.key != 1) return "priv/muro/http/session.muro:53 session conn: end";
  return muro__sess_label(st.key, st.at);
}

void muro__sess_conn_expected(muro__sess_st st, char *buf, size_t n) {
  if (!buf || n == 0) return;
  if (st.key != 1 || st.stuck || st.at == 0) {
    muro__sess_lit(buf, n, "done");
    return;
  }
  muro__sess_exp_at(st.at, &st, buf, n);
}

