muro__sess_res muro__sess_peer_step_word(muro__sess_st st, int dir, int tag, uint64_t word) {
  return muro__sess_word_step(st, dir, tag, word, muro__sess_peer_step);
}

int muro__sess_peer_done(muro__sess_st st) {
  if (st.key != 2) return 0;
  return muro__sess_is_done(st.key, st.at, st.stuck);
}

const char *muro__sess_peer_at(muro__sess_st st) {
  if (st.key != 2) return "priv/muro/http/session.muro:69 session peer: end";
  return muro__sess_label(st.key, st.at);
}

void muro__sess_peer_expected(muro__sess_st st, char *buf, size_t n) {
  if (!buf || n == 0) return;
  if (st.key != 2 || st.stuck || st.at == 0) {
    muro__sess_lit(buf, n, "done");
    return;
  }
  muro__sess_exp_at(st.at, &st, buf, n);
}

muro__sess_res muro__sess_init(const char *name, const uint64_t *args, size_t n) {
  muro__sess_res res;
  memset(&res, 0, sizeof res);
  res.status = MURO_SESS_INIT;
  res.step = "";
  muro__sess_lit(res.expected, sizeof res.expected, "done");
  (void)args;
  if (!name) return res;
  if (strcmp(name, "conn") == 0 && n == 0) {
    return muro__sess_conn_init();
  }
  if (strcmp(name, "peer") == 0 && n == 0) {
    return muro__sess_peer_init();
  }
  return res;
}

muro__sess_res muro__sess_step(const char *name, muro__sess_st st, int dir, const muro__sess_val *value) {
  muro__sess_res res;
  memset(&res, 0, sizeof res);
  res.status = MURO_SESS_UNEXPECTED;
  res.state = st;
  res.step = "";
  muro__sess_lit(res.expected, sizeof res.expected, "done");
  if (!name) return res;
  if (strcmp(name, "conn") == 0) return muro__sess_conn_step(st, dir, value);
  if (strcmp(name, "peer") == 0) return muro__sess_peer_step(st, dir, value);
  return res;
}

muro__sess_res muro__sess_step_word(const char *name, muro__sess_st st, int dir, int tag, uint64_t word) {
  muro__sess_res res;
  memset(&res, 0, sizeof res);
  res.status = MURO_SESS_UNEXPECTED;
  res.state = st;
  res.step = "";
  muro__sess_lit(res.expected, sizeof res.expected, "done");
  (void)dir;
  (void)tag;
  (void)word;
  if (!name) return res;
  if (strcmp(name, "conn") == 0) return muro__sess_conn_step_word(st, dir, tag, word);
  if (strcmp(name, "peer") == 0) return muro__sess_peer_step_word(st, dir, tag, word);
  return res;
}

int muro__sess_done(const char *name, muro__sess_st st) {
  if (name && strcmp(name, "conn") == 0) return muro__sess_conn_done(st);
  if (name && strcmp(name, "peer") == 0) return muro__sess_peer_done(st);
  return 0;
}

const char *muro__sess_at(const char *name, muro__sess_st st) {
  if (name && strcmp(name, "conn") == 0) return muro__sess_conn_at(st);
  if (name && strcmp(name, "peer") == 0) return muro__sess_peer_at(st);
  return "";
}

void muro__sess_expected(const char *name, muro__sess_st st, char *buf, size_t n) {
  if (!buf || n == 0) return;
  muro__sess_lit(buf, n, "done");
  if (name && strcmp(name, "conn") == 0) {
    muro__sess_conn_expected(st, buf, n);
    return;
  }
  if (name && strcmp(name, "peer") == 0) {
    muro__sess_peer_expected(st, buf, n);
    return;
  }
}
